{
  "interpretation": {
    "name": "Line2TightenThenReturnTool",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Bring the shared nutrunner NR7 to station st2, tighten the fasteners of variant F30, and send the tool back to the crib immediately afterwards, while evaluation and recording run in parallel with the return trip.",
    "constraints": [
      "The tool is reserved before use and released after the return transport",
      "The tool is at the station before configure-tool and tighten-fasteners",
      "The tightening program comes only from get-program",
      "The return transport starts right after tighten-fasteners completes",
      "The tightening is evaluated against its program and recorded for traceability",
      "transport-tool is delegated to the executor agvexecutor",
      "Every tool-using step renews the lease with the reservation token"
    ],
    "preference": "Minimise the time the tool is held by running evaluation and recording in parallel with the return transport.",
    "priority": "normal",
    "horizon": "Single execution for the current request",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-nr7-tighten-and-return",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "deliver",
        "steps": [
          {
            "name": "reserve-tool-step",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "get-program-step",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "deliver",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station-step",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-tool-step"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "finish",
        "steps": [
          {
            "name": "configure-tool-step",
            "service": "configure-tool",
            "next": ["tighten-fasteners-step"],
            "dep": ["get-program-step", "reserve-tool-step", "transport-to-station-step"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-fasteners-step",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure-tool-step", "reserve-tool-step", "transport-to-station-step"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "finish",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib-step",
            "service": "transport-tool",
            "next": ["release-tool-step"],
            "dep": ["reserve-tool-step", "tighten-fasteners-step"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "evaluate-tightening-step",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-fasteners-step", "get-program-step"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-tightening-step",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-fasteners-step"],
            "executor": null,
            "params": {}
          },
          {
            "name": "release-tool-step",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-tool-step", "transport-to-crib-step"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
